			/// the log. On a real grammar that is four or five times shorter, which is the
			/// difference between a table that fits in the first cache and one that does not.
			/// </remarks>
			internal int Records;

			/// <summary>Which record finished most recently: the number a caller captures.</summary>
			internal int Last = -1;

			/// <summary>
			/// How much of the log the values built for a guard still stand for: a record
			/// below this that was built need not be built again, and one above it was
			/// written since — the log was put back past it and has grown again.
			/// </summary>
			internal int Built;

			/// <summary>
			/// Captures collected while a rule runs and gathered into its record at the end:
			/// three integers each — the slot, and either a record and -1, or a start and end.
			/// </summary>
			internal int[] Refs = new int[48];

			/// <summary>How much of the side stack is in use.</summary>
			internal int RefsCount;

			/// <summary>Where the record being written begins, and which record it is.</summary>
			/// <remarks>
			/// Once it is closed, where the last one begins: a guard asking for the record it just
			/// captured is handed its place without a walk of the log to find it.
			/// </remarks>
			internal int Opened;
			int _number;

			[global::System.ThreadStatic]
			static Ways? _spare;

			/// <summary>Spares below the one slot, for parses reached from inside others; made the first time one is.</summary>
			[global::System.ThreadStatic]
			static Ways?[]? _deeper;

			[global::System.ThreadStatic]
			static int _deeperCount;

			/// <summary>A tape too large for the ordinary slot, kept while the work still wants it.</summary>
			[global::System.ThreadStatic]
			static Ways? _large;

			/// <summary>Parses in a row that did not use the room; at <c>LargeIdle</c> it is let go of.</summary>
			[global::System.ThreadStatic]
			static int _largeIdle;

			/// <summary>And where it goes then: reachable while nothing else wants the memory.</summary>
			[global::System.ThreadStatic]
			static global::System.WeakReference<Ways>? _largeLetGo;

			/// <summary>Parses in a row that left most of the ordinary spare's room unused.</summary>
			[global::System.ThreadStatic]
			static int _spareIdle;

			/// <summary>And where the ordinary spare goes when it has been too big for too long.</summary>
			[global::System.ThreadStatic]
			static global::System.WeakReference<Ways>? _spareLetGo;

			/// <summary>
			/// Eight is a claim, not a taste: if eight parses in a row have not wanted the large
			/// tape, this thread's work has changed and the next parse is unlikely to want it
			/// either. Holding it through a few small parses costs the memory we were holding a
			/// moment ago anyway; holding it through a hundred would be hoarding.
			/// </summary>
			const int LargeIdle = 8;

			/// <summary>The same count for the ordinary slot, read the same way.</summary>
			const int SpareIdle = 8;

			internal static Ways Rent()
			{
				var spare = _spare;

				if (spare != null)
					_spare = null;
				else if (_deeperCount > 0)
				{
					spare = _deeper![--_deeperCount]!;
					_deeper![_deeperCount] = null;
				}
				else if (_large != null)
				{
					spare = _large;
					_large = null;
				}
				else if (_largeLetGo != null && _largeLetGo.TryGetTarget(out var letGo))
				{
					spare = letGo;
					_largeLetGo.SetTarget(null!);
				}
				else if (_spareLetGo != null && _spareLetGo.TryGetTarget(out var letGoSpare))
				{
					spare = letGoSpare;
					_spareLetGo.SetTarget(null!);
				}
				else
					return new Ways();
				spare.Count = 0;
				spare.Cursor = 0;
				spare.LogCount  = 0;
				spare.Records   = 0;
				spare.RefsCount = 0;
				spare.Last      = -1;
				spare.Built     = 0;

				return spare;
			}

			internal static void Return(Ways ways)
			{
				// Bound retained capacity, including an earlier parse's high-water size. Past it
				// the tape is not thrown away — that was a cliff rather than a bound: one entry
				// over and the next parse of a document that size grew everything again from
				// nothing, which cost twenty times the memory of a document a third smaller.
				// It goes to a slot of its own instead, held while the work keeps wanting it
				// (Return, LargeIdle) and let go of by the collector afterwards. Handing it to
				// ArrayPool<T>.Shared instead was considered and is not the same thing: that
				// pool's largest kept array is 2^20 elements, the very number this bound is
				// written in, so it would decline exactly these arrays and "pool it" would mean
				// "drop it" in more words.
				if ((long)ways.Items.Length + ways.Log.Length + ways.Refs.Length > 1048576)
				{
					if (_large != null && !ReferenceEquals(_large, ways))
						(_largeLetGo ??= new global::System.WeakReference<Ways>(_large)).SetTarget(_large);

					// The same question the ordinary slot asks below: is the room far larger than the
					// use. The bound decides which slot holds the tape, not whether to keep it.
					if (!((long)ways.Items.Length + ways.Log.Length + ways.Refs.Length
						> 4L * (ways.Count * 2L + ways.LogCount + ways.RefsCount)))
						_largeIdle = 0;
					else if (++_largeIdle >= LargeIdle)
					{
						(_largeLetGo ??= new global::System.WeakReference<Ways>(ways)).SetTarget(ways);
						_large = null;
						_largeIdle = 0;

						return;
					}

					_large = ways;

					return;
				}

				// The ordinary slot lets go by the rule the parked one uses, counted where a parse
				// ENDS and against what it used. Room and use are the two sums already written above:
				// every array here is indexed by the same thing, so the bound's capacities and the
				// release's counts are the same quantity twice. Four times and not twice because a
				// table grows to at least double: one doubling is the slack a steady workload leaves,
				// and two is a workload that has shrunk.
				if (!((long)ways.Items.Length + ways.Log.Length + ways.Refs.Length
					> 4L * (ways.Count * 2L + ways.LogCount + ways.RefsCount)))
					_spareIdle = 0;
				else if (++_spareIdle >= SpareIdle)
				{
					(_spareLetGo ??= new global::System.WeakReference<Ways>(ways)).SetTarget(ways);
					_spareIdle = 0;

					return;
				}

				if (_spare == null)
					_spare = ways;
				else if (_deeperCount < 3)
					(_deeper ??= new Ways?[3])[_deeperCount++] = ways;
			}

			/// <summary>Opens a way at the end of the tape, in force at its first alternative.</summary>
			internal int Open(int last) => Open(0, last);

			/// <summary>Opens a way at the end of the tape, in force at <paramref name="at"/>.</summary>
			internal int Open(int at, int last)
			{
				if (Count * 2 + 2 > Items.Length)
					global::System.Array.Resize(ref Items, Items.Length * 2);

				Items[Count * 2]     = at;
				Items[Count * 2 + 1] = last;
				Count++;
				Cursor = Count;

				return Count - 1;
			}

			/// <summary>
			/// Takes the latest way decided since <paramref name="segment"/> that still has an
			/// alternative left, drops everything decided after it, and sets the replay to
			/// begin at the segment. False when none is left, and then nothing moves.
			/// </summary>
			/// <remarks>
			/// Only what stands before the cursor is the construct's own. During a replay the
			/// tape past the cursor is the future — decisions of what comes after, waiting to
			/// be read again — and a construct that fails on the way there, exactly as it did
			/// the first time, must leave that future alone.
			/// </remarks>
			internal bool Retry(int segment)
			{
				for (var way = Cursor - 1; way >= segment; way--)
				{
					if (Items[way * 2] < Items[way * 2 + 1])
					{
						Items[way * 2]++;
						Count  = way + 1;
						Cursor = segment;

						return true;
					}
				}

				return false;
			}

			/// <summary>
			/// Moves a way on to its next alternative once the one in force is spent, and
			/// drops what that alternative decided: the next one starts from nothing.
			/// </summary>
			internal void Next(int way, int value)
			{
				Items[way * 2] = value;
				Count  = way + 1;
				Cursor = way + 1;
			}

			/// <summary>
			/// <see cref="Next(int, int)"/>, and the way now reaches <paramref name="last"/>:
			/// as far as the alternative it moved to could be mended from.
			/// </summary>
			internal void Next(int way, int value, int last)
			{
				Items[way * 2]     = value;
				Items[way * 2 + 1] = last;
				Count  = way + 1;
				Cursor = way + 1;
			}

			/// <summary>Spends every way decided since the segment, keeping its decision.</summary>
			internal void Seal(int segment)
			{
				for (var way = segment; way < Cursor; way++)
					Items[way * 2 + 1] = Items[way * 2];
			}

			/// <summary>
			/// Opens a record: its length is written when it ends.
			/// </summary>
			/// <remarks>
			/// One number says which rule wrote it and which of that rule's alternatives,
			/// because the walk at the end wants both together and asking twice cost a
			/// switch inside a switch — two jump tables where a record needs one.
			/// </remarks>
			/// <summary>
			/// Opens a record that stands nowhere in particular: where nothing a machine
			/// builds is a span of the input, and no factory it runs asks where it read,
			/// the two positions are two integers written and never looked at.
			/// </summary>
			[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
			internal void Begin(int arm)
			{
				if (LogCount + 2 > Log.Length)
					global::System.Array.Resize(ref Log, Log.Length * 2 + 2);

				Opened = LogCount;
				_number = Records++;
				Log[LogCount++] = 0;
				Log[LogCount++] = arm;
			}

			[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
			internal void Begin(int arm, int start, int end)
			{
				if (LogCount + 4 > Log.Length)
					global::System.Array.Resize(ref Log, Log.Length * 2 + 4);

				Opened = LogCount;
				_number = Records++;
				Log[LogCount++] = 0;
				Log[LogCount++] = arm;
				Log[LogCount++] = start;
				Log[LogCount++] = end;
			}

			[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
			internal void Put(int value)
			{
				if (LogCount + 1 > Log.Length)
					global::System.Array.Resize(ref Log, Log.Length * 2 + 1);

				Log[LogCount++] = value;
			}

			[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
			internal void Put(int a, int b)
			{
				if (LogCount + 2 > Log.Length)
					global::System.Array.Resize(ref Log, Log.Length * 2 + 2);

				Log[LogCount++] = a;
				Log[LogCount++] = b;
			}

			/// <summary>Closes the record: its length goes in front, and it becomes the last.</summary>
			[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
			internal void End(int refs)
			{
				Log[Opened] = LogCount - Opened;
				Last         = _number;
				RefsCount    = refs;
			}

			/// <summary>
			/// The record closed, and named by where it stands rather than by its number:
			/// an extent is the one thing whose value is the record itself, read straight
			/// out of the log by whoever captured it, and never put in a table.
			/// </summary>
			[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
			internal void EndAt(int refs)
			{
				Log[Opened] = LogCount - Opened;
				Last         = Opened;
				RefsCount    = refs;
			}

			/// <summary>
			/// A mark placed or taken away (docs/syntax.md §7.8): a record of its own in the
			/// log, so that what was put back with the log takes its marks with it. The kind
			/// is -1 where the mark opens and -2 where it closes; nothing captures one.
			/// </summary>
			internal void Mark(int kind, int site, int at)
			{
				if (LogCount + 5 > Log.Length)
					global::System.Array.Resize(ref Log, Log.Length * 2 + 5);

				Records++;

				Log[LogCount++] = 5;
				Log[LogCount++] = kind;
				Log[LogCount++] = site;
				Log[LogCount++] = at;
				Log[LogCount++] = at;
			}

			/// <summary>A capture made inside a repetition, kept until the rule gathers it.</summary>
			internal void Push(int slot, int a, int b)
			{
				if (RefsCount + 3 > Refs.Length)
					global::System.Array.Resize(ref Refs, Refs.Length * 2 + 3);

				Refs[RefsCount++] = slot;
				Refs[RefsCount++] = a;
				Refs[RefsCount++] = b;
			}

			/// <summary>
			/// Writes what was pushed for the given slots since <paramref name="from"/>: how
			/// many, then each one — the record alone where <paramref name="pairs"/> is false,
			/// the start and end where it is true.
			/// </summary>
			internal void Collect(int from, long slots, bool pairs)
			{
				var count = 0;

				for (var at = from; at < RefsCount; at += 3)
					if ((slots & (1L << Refs[at])) != 0)
						count++;

				Put(count);

				for (var at = from; at < RefsCount; at += 3)
					if ((slots & (1L << Refs[at])) != 0)
					{
						if (pairs)
							Put(Refs[at + 1], Refs[at + 2]);
						else
							Put(Refs[at + 1]);
					}
			}
		}

		/// <summary>Records a refusal against the furthest one seen, as the engine's Fail does.</summary>
		static void Refuse_DotGram(ref Failure failure, int at, string[]? expected)
		{
			if (failure.Looking > 0)
				return;

			if (at > failure.Position)
			{
				failure.Position     = at;
				failure.Expected     = expected;
				failure.ExpectedMore?.Clear();
			}
			else if (at == failure.Position && expected != null && !ReferenceEquals(expected, failure.Expected))
			{
				// The same set said twice is one thing wanted, not two. A rule refused at the
				// furthest position by several of its alternatives says the same set from
				// each, and a message listing it once is the message; a list holding it
				// several times is a list that grew on a parse that went on to succeed.
				var more = failure.ExpectedMore;

				if (more == null)
					failure.ExpectedMore = more = new global::System.Collections.Generic.List<string[]>();
				else if (more.Count > 0 && ReferenceEquals(more[more.Count - 1], expected))
					return;

				more.Add(expected);
			}
		}

		/// <summary>
		/// Records what a choice wanted where the call that begins its widest group refused at the
		/// same place: that call's own set, which the choice's holds, is dropped for it.
		/// </summary>
		static void Refuse_DotGram_Over(ref Failure failure, int at, string[] expected, string[] covered)
		{
			if (failure.Looking > 0)
				return;

			if (at == failure.Position)
			{
				if (ReferenceEquals(failure.Expected, covered))
					failure.Expected = expected;

				failure.ExpectedMore?.Remove(covered);
			}

			Refuse_DotGram(ref failure, at, expected);
		}

		/// <summary>How much of a run matched, asked only when it did not.</summary>
		static int Reach_DotGram(
			global::System.ReadOnlySpan<char> text, int pos, global::System.ReadOnlySpan<char> want)
		{
			var room = text.Length - pos;

			if (want.Length < room)
				room = want.Length;

			var at = 0;

			while (at < room && text[pos + at] == want[at])
				at++;

			return pos + at;
		}

		sealed class DirectValues
		{
			internal Held<int>[] V0 = new Held<int>[16];
			internal bool[] Live   = new bool[16];
			internal int[]  Starts = new int[16];
			internal bool[] Built  = new bool[16];
			int _used;

			[global::System.ThreadStatic]
			static DirectValues? _spare;

			/// <summary>Spares below the one slot, for parses reached from inside others; made the first time one is.</summary>
			[global::System.ThreadStatic]
			static DirectValues?[]? _deeper;

			[global::System.ThreadStatic]
			static int _deeperCount;

			/// <summary>A store past the bound, kept while this thread's work still wants it.</summary>
			[global::System.ThreadStatic]
			static DirectValues? _large;

			/// <summary>Parses in a row that did not use the room; at <c>LargeIdle</c> it is let go of.</summary>
			[global::System.ThreadStatic]
			static int _largeIdle;

			/// <summary>And where it goes then: reachable until the memory is wanted elsewhere.</summary>
			[global::System.ThreadStatic]
			static global::System.WeakReference<DirectValues>? _largeLetGo;

			/// <summary>Parses in a row that left most of the ordinary spare's room unused.</summary>
			[global::System.ThreadStatic]
			static int _spareIdle;

			/// <summary>And where the ordinary spare goes when it has been too big for too long.</summary>
			[global::System.ThreadStatic]
			static global::System.WeakReference<DirectValues>? _spareLetGo;

			/// <summary>
			/// Eight is a claim rather than a taste: if eight parses in a row have not wanted
			/// the room a slot holds - the large store, or an ordinary spare far bigger than
			/// the parses that keep coming - this thread's work has changed and the next parse is unlikely
			/// to want it either. Carrying it through a few small parses costs the memory this
			/// thread held a moment ago anyway; carrying it through a hundred would be hoarding.
			///
			/// Counted where a parse ENDS, against what that parse USED. At the rental it
			/// could never arrive: a rental that takes the kept store zeroes the count, and
			/// with no ordinary spare - the state right after a large parse - every rental
			/// takes it. Against CAPACITY it could never arrive either: a store comes back
			/// as large as it was grown, whatever the document was.
			/// </summary>
			const int LargeIdle = 8;

			/// <summary>The same count for the ordinary slot, read the same way.</summary>
			const int SpareIdle = 8;

			internal static DirectValues Rent()
			{
				var spare = _spare;

				if (spare != null)
					_spare = null;
				else if (_deeperCount > 0)
				{
					spare = _deeper![--_deeperCount]!;
					_deeper![_deeperCount] = null;
				}
				else if (_large != null)
				{
					spare = _large;
					_large = null;
				}
				else if (_largeLetGo != null && _largeLetGo.TryGetTarget(out var letGo))
				{
					spare = letGo;
					_largeLetGo.SetTarget(null!);
				}
				else if (_spareLetGo != null && _spareLetGo.TryGetTarget(out var letGoSpare))
				{
					spare = letGoSpare;
					_spareLetGo.SetTarget(null!);
				}
				else
					return new DirectValues();

				return spare;
			}

			internal static void Return(DirectValues values)
			{
				var rows = values._used;

				global::System.Array.Clear(values.V0, 0, global::System.Math.Min(values._used, values.V0.Length));
				global::System.Array.Clear(values.Built, 0, global::System.Math.Min(values._used, values.Built.Length));
				values._used = 0;

				// Past the bound the store is not thrown away - that was a cliff
				// and not a bound - it is kept while the work keeps wanting it, and handed
				// to the collector once it stops (CSharpEmitter.Outsized). It is emptied
				// first, above: what is kept is the room, never what was built in it.
				if (0L + values.V0.Length + values.Live.Length + values.Starts.Length + values.Built.Length > 1048576)
				{
					// The same question the ordinary slot asks below: is the room far larger than
					// the use. The bound decides WHICH slot holds the store; it does not decide
					// whether to keep it. This read the parse's use against the BOUND until
					// 2026-09-21, and for a dense store the two are not the same quantity: the
					// room counts three hundred value tables and the use counted only records, so
					// a parse that had just filled a seventeen-megabyte store read as idle and the
					// eighth STEADY parse of the same document threw the store away and rebuilt it.
					if (!(values.Live.Length > 4L * rows))
						_largeIdle = 0;
					else if (++_largeIdle >= LargeIdle)
					{
						(_largeLetGo ??= new global::System.WeakReference<DirectValues>(values)).SetTarget(values);
						_large = null;
						_largeIdle = 0;

						return;
					}

					if (_large != null && !ReferenceEquals(_large, values))
						(_largeLetGo ??= new global::System.WeakReference<DirectValues>(_large)).SetTarget(_large);

					_large = values;

					return;
				}

				// The ordinary slot lets go by the same rule as the parked one: counted where a
				// parse ENDS, against what that parse USED. At the rental it could not arrive,
				// for the reason written above LargeIdle. And it is let go of WEAKLY, so a thread that
				// wants the room straight back still gets it, while one that does not has stopped
				// holding it against everybody else.
				if (!(values.Live.Length > 4L * rows))
					_spareIdle = 0;
				else if (++_spareIdle >= SpareIdle)
				{
					(_spareLetGo ??= new global::System.WeakReference<DirectValues>(values)).SetTarget(values);
					_spareIdle = 0;

					return;
				}

				if (_spare == null)
					_spare = values;
				else if (_deeperCount < 3)
					(_deeper ??= new DirectValues?[3])[_deeperCount++] = values;
			}

			/// <summary>Room for a value at every index below the count; what was built stays built.</summary>
			internal void Room(int count, bool live = true, int from = 0)
			{
				if (count > _used) _used = count;
				if (Live.Length < count)
				{
					Live   = new bool[global::System.Math.Max(count, Live.Length * 2)];
					Starts = new int[Live.Length];
					var built = new bool[Live.Length];
					global::System.Array.Copy(Built, built, Built.Length);
					Built  = built;
				}
				else if (live && count > from)
					global::System.Array.Clear(Live, from, count - from);
				if (V0.Length < count)
					global::System.Array.Resize(ref V0, global::System.Math.Max(count, V0.Length * 2));
			}
		}

		/// <summary>One value in a table, in a struct so that storing it asks nothing.</summary>
		#pragma warning disable CS0649 // a table nothing writes still declares the field
		struct Held<T>
		{
			internal T Value;
		}
		#pragma warning restore CS0649

	}
